#include "web_pages.h"

namespace web_pages {

std::string capture_html() {
    return std::string(R"HTML(<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1">)HTML") + common_style() + R"HTML(</head><body><div class="top"><nav class="nav"><span class="brand">数据集拍摄</span><a class="back" href="/">返回服务选择</a></nav></div><main class="wrap"><header class="capture-head"><div><h1>数据集拍摄</h1><span class="muted">采集停止时不会请求实时画面或轮询状态</span></div><div class="run-control"><span id="runState" class="state">已停止</span><button id="captureStart" class="primary" onclick="startCapture()">开始采集</button><button id="captureStop" onclick="stopCapture()" disabled>停止采集</button></div></header><div class="grid"><section class="panel"><div id="liveStage" class="live-stage paused"><div class="live"><img id="live" alt="实时画面"></div><div class="paused-note">采集已停止</div></div><div class="tool-section"><span class="tool-title">图片操作</span><div class="action-row"><button id="saveButton" class="primary" onclick="captureImage()" disabled>保存图片</button><button id="classifyButton" onclick="classifyImage()" disabled>识别当前图片</button></div></div><div class="tool-section"><span class="tool-title">图片序号</span><div class="sequence"><button onclick="seqDelta(-1)">−1</button><input class="seqinput" id="seq" type="number" min="0" step="1" value="0" onfocus="seqEditing=true" oninput="seqEditing=true" onblur="setSeq()"><button onclick="seqDelta(1)">+1</button></div></div><p id="msg" class="muted"></p><pre id="cls"></pre></section><aside class="panel"><label>保存目录</label><div class="row"><input class="grow" id="captureDir" placeholder="/home/root/image/ 或相对目录" onfocus="dirEditing=true" oninput="dirEditing=true" onblur="dirEditing=false"><button onclick="setCaptureDir()">应用目录</button></div><p class="muted">仅允许 /home/root/image/ 及其子目录；不存在的目录会自动创建。</p><label>保存前缀</label><div class="row"><input class="grow" id="prefix" maxlength="32" onfocus="prefixEditing=true" oninput="prefixEditing=true" onblur="prefixEditing=false"><button onclick="setPrefix()">保存</button></div><div class="status-list"><div><span>障碍识别</span><strong id="barrier">-</strong></div><div><span>无环岛选线</span><strong id="lineChoice">-</strong></div><div><span>电池电压</span><strong id="battery">-</strong></div></div></aside></div><section class="panel" style="margin-top:16px"><div class="row"><strong>已保存图片</strong><button onclick="refreshOnce()">刷新列表</button></div><div id="images" class="images"></div></section></main><script>
let prefixEditing=false,dirEditing=false,seqEditing=false,statusTimer=null,frameTimer=null,processing=false;function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function api(p,o){let r=await fetch(p,o);return r.json()}function stopPolling(){if(statusTimer){clearInterval(statusTimer);statusTimer=null}if(frameTimer){clearInterval(frameTimer);frameTimer=null}}function startPolling(){stopPolling();reloadLive();frameTimer=setInterval(reloadLive,300);statusTimer=setInterval(refreshStatus,1500)}function reloadLive(){if(processing)live.src='/api/frame?t='+Date.now()}function render(s,force=false){processing=!!s.capture_processing;if(force||!prefixEditing)prefix.value=s.prefix;if(force||!dirEditing)captureDir.value=s.capture_dir;if(force||!seqEditing)seq.value=s.img_seq;barrier.innerText=s.barrier_flag;lineChoice.innerText=s.line_chose_without_circle;battery.innerText=s.battery;msg.innerText=s.message;cls.innerText=s.classify;captureStart.disabled=processing;captureStop.disabled=!processing;saveButton.disabled=!processing;classifyButton.disabled=!processing;runState.innerText=processing?'采集中':'已停止';runState.classList.toggle('running',processing);liveStage.classList.toggle('paused',!processing);images.innerHTML=s.images.map(n=>`<div class=item><a href="/image?name=${encodeURIComponent(n)}" target=_blank><img src="/image?name=${encodeURIComponent(n)}"></a><small>${esc(n)}</small><button class=danger onclick="delImage('${n}')">删除</button></div>`).join('');if(processing){if(!statusTimer)startPolling()}else stopPolling()}async function refreshStatus(force=false){render(await api('/api/status'),force)}async function refreshOnce(){await refreshStatus()}async function setCaptureDir(){dirEditing=false;render(await api('/api/capture-dir',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'dir='+encodeURIComponent(captureDir.value)}),true)}async function setPrefix(){prefixEditing=false;render(await api('/api/prefix',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'prefix='+encodeURIComponent(prefix.value)}),true)}async function seqDelta(d){seqEditing=false;render(await api('/api/seq',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'delta='+d}),true)}async function setSeq(){seqEditing=false;render(await api('/api/seq',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'seq='+encodeURIComponent(seq.value||0)}),true)}async function startCapture(){render(await api('/api/capture/start',{method:'POST'}),true)}async function stopCapture(){render(await api('/api/capture/stop',{method:'POST'}),true)}async function captureImage(){render(await api('/api/capture',{method:'POST'}))}async function classifyImage(){render(await api('/api/classify',{method:'POST'}))}async function delImage(n){if(confirm('删除 '+n+' ?'))render(await api('/api/delete',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'name='+encodeURIComponent(n)}))}async function stopServer(){stopPolling();await api('/api/stop',{method:'POST'});msg.innerText='网页服务正在退出'}refreshStatus(true);
</script></body></html>)HTML";
}

} // namespace web_pages
